def icone(tamanho: int) -> str:
    return _ICONE.replace("TAM", str(tamanho))


def logotipo(largura: int, cor1: str = "#0B1B46", cor2: str = "#4FA8FF") -> str:
    return _LOGOTIPO.replace("LARG", str(largura)).replace("ALT", str(round(largura * 33 / 145))).replace("COR1", cor1).replace("COR2", cor2)


def marca(altura_icone: int = 80, largura_logotipo: int = 250, cor1: str = "#0B1B46", cor2: str = "#4FA8FF") -> str:
    return (
        f'<span style="display:inline-flex;align-items:center;gap:10px">{icone(altura_icone)}'
        f"{logotipo(largura_logotipo, cor1, cor2)}</span>"
    )
